CREATE OR REPLACE FUNCTION public._admin_messages_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'UPDATE' then raise exception 'messages are append-only'; end if;
  if tg_op = 'DELETE' then
    if pg_trigger_depth() = 1 then raise exception 'messages are append-only'; end if;
    return old;
  end if;
  if new.kind in ('to_recipient','internal_note','offline_log') and not exists (select 1 from public.platform_admins pa where pa.user_id = new.author_user_id) then
    raise exception 'only admins can write this kind of message';
  end if;
  if new.kind = 'from_recipient' and not public._admin_thread_visible_to(new.thread_id, new.author_user_id) then
    raise exception 'author cannot access this thread';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public._cancel_interest_notifications(p_interest_id uuid, p_store_id uuid, p_stylist_user_id uuid, p_kind text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_legacy uuid; n_id uuid; v_count integer := 0;
begin
  v_legacy := case p_kind when 'trial' then md5(p_store_id::text || ':' || p_stylist_user_id::text || ':trial')::uuid else md5(p_store_id::text || ':' || p_stylist_user_id::text)::uuid end;
  for n_id in
    update public.notifications set cancelled_at = now(), cancel_reason = 'interest_cancelled'
      where type = 'stylist_interest_received' and related_entity_type = 'store_interest' and related_entity_id in (p_interest_id, v_legacy) and cancelled_at is null
      returning id
  loop
    perform public._email_cancel_for_notification(n_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_assign_visit_request(p_id uuid, p_admin uuid, p_expected_updated_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid := auth.uid(); r public.admin_visit_requests;
begin
  if not public.is_platform_admin() then raise exception 'admin access required'; end if;
  if p_admin is not null and not exists (select 1 from public.platform_admins where user_id = p_admin) then raise exception 'assignee must be an admin'; end if;
  select * into r from public.admin_visit_requests where id = p_id for update;
  if not found then raise exception 'request not found'; end if;
  if r.updated_at is distinct from p_expected_updated_at then raise exception 'request was updated by someone else'; end if;
  if r.status in ('attended', 'closed') then raise exception 'request is already finished'; end if;
  update public.admin_visit_requests set assigned_admin_id = p_admin where id = r.id;
  insert into public.admin_visit_request_events (request_id, actor_user_id, action, before_value, after_value)
    values (r.id, v_uid, 'assigned', jsonb_build_object('assigned_admin_id', r.assigned_admin_id), jsonb_build_object('assigned_admin_id', p_admin));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_claim_visit_request(p_source_kind text, p_source_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid := auth.uid(); v_kind text; v_stylist uuid; v_store uuid; v_id uuid;
begin
  if not public.is_platform_admin() then raise exception 'admin access required'; end if;
  if p_source_kind = 'scout_reply' then
    select case s.response_status when 'visit_requested' then 'visit' when 'trial_requested' then 'trial' else null end, s.stylist_user_id, s.store_id
      into v_kind, v_stylist, v_store from public.scouts s where s.id = p_source_id;
    if not found then raise exception 'source not found'; end if;
    if v_kind is null then raise exception 'source is not a visit or trial request'; end if;   -- 過去の「話を聞いてみたい」等は読み替えない
    if v_store is null then raise exception 'source has no store'; end if;
    insert into public.admin_visit_requests (source_kind, source_scout_id, kind, stylist_user_id, store_id, assigned_admin_id)
      values ('scout_reply', p_source_id, v_kind, v_stylist, v_store, v_uid) on conflict do nothing returning id into v_id;
    if v_id is null then select id into v_id from public.admin_visit_requests where source_scout_id = p_source_id; return v_id; end if;
  elsif p_source_kind = 'direct_interest' then
    select i.stylist_user_id, i.store_id, i.kind into v_stylist, v_store, v_kind from public.stylist_salon_interests i where i.id = p_source_id;
    if not found then raise exception 'source not found'; end if;
    if v_store is null then raise exception 'source has no store'; end if;
    insert into public.admin_visit_requests (source_kind, source_interest_id, kind, stylist_user_id, store_id, assigned_admin_id)
      values ('direct_interest', p_source_id, v_kind, v_stylist, v_store, v_uid) on conflict do nothing returning id into v_id;
    if v_id is null then select id into v_id from public.admin_visit_requests where source_interest_id = p_source_id; return v_id; end if;
  else
    raise exception 'invalid source kind';
  end if;
  insert into public.admin_visit_request_events (request_id, actor_user_id, action, after_value)
    values (v_id, v_uid, 'claimed', jsonb_build_object('status', 'received', 'assigned_admin_id', v_uid, 'source_kind', p_source_kind));
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_get_visit_request(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb;
begin
  if not public.is_platform_admin() then raise exception 'admin access required'; end if;
  select to_jsonb(r) || jsonb_build_object(
      'source_cancelled', (case r.source_kind when 'direct_interest' then not exists (select 1 from public.stylist_salon_interests i where i.id = r.source_interest_id) else not exists (select 1 from public.scouts s where s.id = r.source_scout_id) end),
      'confirmations', coalesce((select jsonb_agg(to_jsonb(c) order by c.party) from public.admin_visit_confirmations c where c.occurrence_id = r.occurrence_id), '[]'::jsonb),
      'events', coalesce((select jsonb_agg(jsonb_build_object('action', e.action, 'actor_user_id', e.actor_user_id, 'before_value', e.before_value, 'after_value', e.after_value, 'created_at', e.created_at) order by e.created_at) from public.admin_visit_request_events e where e.request_id = r.id), '[]'::jsonb))
    into v from public.admin_visit_requests r where r.id = p_id;
  if v is null then raise exception 'request not found'; end if;
  return v;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_post_message(p_request_id uuid, p_thread_id uuid, p_kind text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid := auth.uid(); v_msg uuid; v_hash text; v_prev record; v_body text := btrim(coalesce(p_body, ''));
begin
  if not public.is_platform_admin() then raise exception 'admin access required'; end if;
  if p_request_id is null then raise exception 'request id required'; end if;
  if p_kind not in ('to_recipient','internal_note','offline_log') then raise exception 'invalid kind'; end if;
  if char_length(v_body) = 0 then raise exception 'invalid body'; end if;
  v_hash := public._admin_request_hash('post_message', coalesce(p_thread_id::text,''), p_kind, v_body);
  perform public._admin_lock_request(v_uid, p_request_id);                                   -- ②
  select m.id, m.request_hash into v_prev from public.admin_messages m where m.author_user_id = v_uid and m.request_id = p_request_id;
  if found then
    if v_prev.request_hash <> v_hash then raise exception 'request id content mismatch'; end if;
    return v_prev.id;
  end if;
  perform 1 from public.admin_threads where id = p_thread_id for update;                    -- ③
  if not found then raise exception 'thread not found'; end if;
  insert into public.admin_messages (thread_id, kind, author_user_id, body, request_id, request_hash) values (p_thread_id, p_kind, v_uid, v_body, p_request_id, v_hash) returning id into v_msg;
  if p_kind = 'to_recipient' then
    insert into public.admin_message_deliveries (message_id) values (v_msg);
    update public.admin_threads set status = 'waiting_recipient', updated_at = now() where id = p_thread_id;   -- 完了後の追記は再開になる
  else
    update public.admin_threads set updated_at = now() where id = p_thread_id;
  end if;
  return v_msg;
end $function$

CREATE OR REPLACE FUNCTION public.admin_record_visit_confirmation(p_request_id uuid, p_party text, p_result text, p_channel text, p_note text DEFAULT NULL::text, p_confirmed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid := auth.uid(); r public.admin_visit_requests; o public.admin_visit_occurrences; v_before jsonb;
begin
  if not public.is_platform_admin() then raise exception 'admin access required'; end if;
  if p_party not in ('salon', 'stylist') then raise exception 'invalid party'; end if;
  if p_result not in ('held', 'not_held') then raise exception 'invalid result'; end if;
  if p_channel not in ('message', 'phone', 'other') then raise exception 'invalid channel'; end if;
  if p_note is not null and char_length(p_note) > 1000 then raise exception 'note too long'; end if;
  -- ロック順: 実施単位 → 受付（update と同じ）
  select * into r from public.admin_visit_requests where id = p_request_id;
  if not found then raise exception 'request not found'; end if;
  if r.occurrence_id is null then raise exception 'confirmations can be recorded only in post_visit_check'; end if;
  select * into o from public.admin_visit_occurrences where id = r.occurrence_id for update;
  select * into r from public.admin_visit_requests where id = p_request_id for update;
  if r.status <> 'post_visit_check' or r.occurrence_id is distinct from o.id then raise exception 'confirmations can be recorded only in post_visit_check'; end if;
  if o.status <> 'post_visit_check' then raise exception 'confirmations can be recorded only in post_visit_check'; end if;
  select jsonb_build_object('result', c.result, 'channel', c.channel) into v_before from public.admin_visit_confirmations c where c.occurrence_id = o.id and c.party = p_party;
  insert into public.admin_visit_confirmations (occurrence_id, party, result, channel, confirmed_at, recorded_by, note)
    values (o.id, p_party, p_result, p_channel, coalesce(p_confirmed_at, now()), v_uid, nullif(btrim(p_note), ''))
    on conflict (occurrence_id, party) do update set result = excluded.result, channel = excluded.channel, confirmed_at = excluded.confirmed_at, recorded_by = excluded.recorded_by, note = excluded.note;
  insert into public.admin_visit_request_events (request_id, actor_user_id, action, before_value, after_value)
    values (r.id, v_uid, 'confirmation_recorded', v_before, jsonb_build_object('party', p_party, 'result', p_result, 'channel', p_channel, 'occurrence_id', o.id));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_thread_status(p_thread_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_old text;
begin
  if not public.is_platform_admin() then raise exception 'admin access required'; end if;
  if p_status not in ('open_internal','waiting_recipient','waiting_admin','done') then raise exception 'invalid status'; end if;
  select status into v_old from public.admin_threads where id = p_thread_id for update;   -- ③
  if not found then raise exception 'thread not found'; end if;
  if v_old = p_status then return; end if;
  update public.admin_threads set status = p_status, updated_at = now() where id = p_thread_id;
  insert into public.admin_audit_events (actor_user_id, action, target_type, target_id, before_value, after_value)
    values (auth.uid(), 'thread_status_changed', 'thread', p_thread_id, jsonb_build_object('status', v_old), jsonb_build_object('status', p_status));
end $function$

CREATE OR REPLACE FUNCTION public.admin_update_visit_request(p_id uuid, p_status text, p_expected_updated_at timestamp with time zone, p_scheduled_on date DEFAULT NULL::date, p_internal_note text DEFAULT NULL::text, p_closed_reason text DEFAULT NULL::text, p_merged_into uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid(); r public.admin_visit_requests; v_before text; v_note text; v_date date; v_target public.admin_visit_requests;
  v_today date := (now() at time zone 'Asia/Tokyo')::date; v_salon text; v_stylist text;
  o public.admin_visit_occurrences; v_old_occ uuid; v_new_occ uuid; sib record; r0 public.admin_visit_requests; v_pre_date date;
begin
  if not public.is_platform_admin() then raise exception 'admin access required'; end if;
  if p_status is null or p_status not in ('received','reviewing','scheduling','scheduled','post_visit_check','attended','closed') then raise exception 'invalid status'; end if;
  -- ロック順（全RPC共通）: ①実施単位（idの昇順）→ ②受付。同じ実施に関連する別入口の受付を同時に更新・実施確定・確認記録しても、
  -- 先に実施単位を取るため互いに待つだけでデッドロックしない（受付だけを先に取る経路を作らない）。
  select * into r0 from public.admin_visit_requests where id = p_id;     -- ロックなしで、関連する実施単位を知る
  if not found then raise exception 'request not found'; end if;
  v_new_occ := null;
  if p_status = 'scheduled' then
    v_pre_date := coalesce(p_scheduled_on, r0.scheduled_on);
    if v_pre_date is not null then
      insert into public.admin_visit_occurrences (stylist_user_id, store_id, kind, visit_date) values (r0.stylist_user_id, r0.store_id, r0.kind, v_pre_date) on conflict do nothing;
      select id into v_new_occ from public.admin_visit_occurrences where stylist_user_id = r0.stylist_user_id and store_id = r0.store_id and kind = r0.kind and visit_date = v_pre_date;
    end if;
  end if;
  perform 1 from public.admin_visit_occurrences x where x.id in (r0.occurrence_id, v_new_occ) order by x.id for update;
  select * into r from public.admin_visit_requests where id = p_id for update;      -- 行ロック: 確認・更新・履歴を同じトランザクションで
  if not found then raise exception 'request not found'; end if;
  if r.occurrence_id is distinct from r0.occurrence_id then raise exception 'request was updated by someone else'; end if;   -- ロックなしで読んだ後に付け替わった
  if r.updated_at is distinct from p_expected_updated_at then raise exception 'request was updated by someone else'; end if;
  if r.status in ('attended', 'closed') then raise exception 'request is already finished'; end if;
  if not public._admin_visit_transition_ok(r.status, p_status) then raise exception 'invalid transition % -> %', r.status, p_status; end if;
  v_before := r.status; v_old_occ := r.occurrence_id;
  v_note := case when p_internal_note is null then r.internal_note else nullif(btrim(p_internal_note), '') end;
  if v_note is not null and char_length(v_note) > 2000 then raise exception 'note too long'; end if;
  v_date := coalesce(p_scheduled_on, r.scheduled_on);
  if p_status in ('scheduled', 'post_visit_check', 'attended') and v_date is null then raise exception 'scheduled date required'; end if;
  if p_status in ('post_visit_check', 'attended') and v_date > v_today then raise exception 'visit date has not come yet'; end if;
  if p_status in ('post_visit_check', 'attended') and p_scheduled_on is not null and p_scheduled_on is distinct from r.scheduled_on then
    raise exception 'change the date while scheduled, not after the visit check started';
  end if;
  if p_status = 'closed' then
    if p_closed_reason is null or p_closed_reason not in ('not_held','declined','duplicate','cancelled','other') then raise exception 'closed reason required'; end if;
    if p_closed_reason = 'duplicate' then
      select * into v_target from public.admin_visit_requests where id = p_merged_into;
      if not found or v_target.id = r.id or v_target.status = 'closed' or v_target.stylist_user_id <> r.stylist_user_id or v_target.store_id <> r.store_id or v_target.kind <> r.kind then
        raise exception 'merge target must be another open request of the same stylist, store and kind';
      end if;
    end if;
  end if;
  -- 実施単位の関連付け（同じ美容師×店舗×種別×実施日は入口が違っても同じ実施単位。ロックは上で取得済み）
  if p_status = 'scheduled' then
    select * into o from public.admin_visit_occurrences where id = v_new_occ;
    if o.status = 'attended' then raise exception 'the same visit is already completed; close this request as duplicate'; end if;
    if o.status = 'cancelled' then update public.admin_visit_occurrences set status = 'scheduled' where id = o.id; end if;
    v_new_occ := o.id;
  elsif p_status in ('post_visit_check', 'attended') then
    select * into o from public.admin_visit_occurrences where id = r.occurrence_id;      -- ロック済み
    v_new_occ := o.id;
    if p_status = 'post_visit_check' and o.status = 'scheduled' then update public.admin_visit_occurrences set status = 'post_visit_check' where id = o.id; end if;
    if p_status = 'attended' then
      select c.result into v_salon from public.admin_visit_confirmations c where c.occurrence_id = o.id and c.party = 'salon';
      select c.result into v_stylist from public.admin_visit_confirmations c where c.occurrence_id = o.id and c.party = 'stylist';
      if v_salon is distinct from 'held' or v_stylist is distinct from 'held' then raise exception 'both parties must confirm the visit was held'; end if;
      if o.status <> 'attended' then update public.admin_visit_occurrences set status = 'attended', attended_at = now() where id = o.id; end if;
    end if;
  end if;
  update public.admin_visit_requests set status = p_status, scheduled_on = case when p_status in ('scheduling','closed') and p_status <> 'scheduling' then r.scheduled_on when p_status = 'scheduling' then v_date else v_date end,
      occurrence_id = case when p_status in ('scheduled','post_visit_check','attended') then v_new_occ when p_status = 'closed' then r.occurrence_id else null end,
      internal_note = v_note, closed_reason = case when p_status = 'closed' then p_closed_reason else null end,
      merged_into_request_id = case when p_status = 'closed' and p_closed_reason = 'duplicate' then p_merged_into else null end
    where id = r.id returning * into r;
  -- 実施単位が誰にも使われなくなり、まだ実施済みでなければ「取消」にする（実施済みは決して動かさない）
  if v_old_occ is not null and v_old_occ is distinct from r.occurrence_id or (p_status = 'closed' and r.occurrence_id is not null) then
    update public.admin_visit_occurrences x set status = 'cancelled'
      where x.id in (v_old_occ, r.occurrence_id) and x.status in ('scheduled', 'post_visit_check')
        and not exists (select 1 from public.admin_visit_requests q where q.occurrence_id = x.id and q.status not in ('closed') and q.id <> r.id)
        and (x.id is distinct from r.occurrence_id or p_status = 'closed');
  end if;
  -- 実施済みにしたとき、同じ実施単位に残る他の未終了の受付（別入口の重複）は「重複」として統合クローズ
  if p_status = 'attended' then
    for sib in select id from public.admin_visit_requests where occurrence_id = r.occurrence_id and id <> r.id and status <> 'closed' for update loop
      update public.admin_visit_requests set status = 'closed', closed_reason = 'duplicate', merged_into_request_id = r.id where id = sib.id;
      insert into public.admin_visit_request_events (request_id, actor_user_id, action, after_value) values (sib.id, v_uid, 'auto_closed_duplicate', jsonb_build_object('merged_into', r.id));
    end loop;
  end if;
  insert into public.admin_visit_request_events (request_id, actor_user_id, action, before_value, after_value)
    values (r.id, v_uid, 'updated', jsonb_build_object('status', v_before), jsonb_build_object('status', r.status, 'scheduled_on', r.scheduled_on, 'closed_reason', r.closed_reason, 'occurrence_id', r.occurrence_id));
  return to_jsonb(r) - 'internal_note';
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_store_recruiting_allowed(p_store_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org uuid;
begin
  select organization_id into v_org from public.salon_stores where id = p_store_id;
  if v_org is null then raise exception 'store not found or not accessible'; end if;
  perform public.assert_organization_recruiting_allowed(v_org);
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_match_axes(p_stylist_user_id uuid, p_salon_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pref public.stylist_preference_profiles;
  v_culture public.salon_culture_profiles;
  v_s_educ numeric; v_s_chal numeric; v_s_brand numeric; v_s_collab numeric;
  v_s_auto numeric; v_s_flex numeric; v_s_reldist numeric; v_s_hier numeric;
  v_c_educ numeric; v_c_chal numeric; v_c_brand numeric; v_c_collab numeric;
  v_c_auto numeric; v_c_flex numeric; v_c_reldist numeric; v_c_hier numeric;
  v_m_educ numeric; v_m_chal numeric; v_m_brand numeric; v_m_collab numeric;
  v_m_auto numeric; v_m_flex numeric; v_m_reldist numeric; v_m_hier numeric;
  v_overall numeric;
begin
  select * into v_pref from public.stylist_preference_profiles where stylist_user_id = p_stylist_user_id;
  select * into v_culture from public.salon_culture_profiles where salon_user_id = p_salon_user_id;

  if v_pref.status is null or v_pref.status != 'completed' then
    return jsonb_build_object('available', false, 'reason', 'stylist_preference_incomplete');
  end if;
  if v_culture.status is null or v_culture.status != 'completed' then
    return jsonb_build_object('available', false, 'reason', 'salon_culture_incomplete');
  end if;

  v_s_educ   := nullif(v_pref.preference_axes->>'education_preference', '')::numeric;
  v_s_chal   := nullif(v_pref.preference_axes->>'challenge_preference', '')::numeric;
  v_s_brand  := nullif(v_pref.preference_axes->>'personal_brand_preference', '')::numeric;
  v_s_collab := nullif(v_pref.preference_axes->>'collaboration_preference', '')::numeric;
  v_s_auto   := nullif(v_pref.preference_axes->>'autonomy_preference', '')::numeric;
  v_s_flex   := nullif(v_pref.preference_axes->>'work_flexibility_preference', '')::numeric;
  v_s_reldist:= nullif(v_pref.preference_axes->>'relationship_distance_preference', '')::numeric;
  v_s_hier   := nullif(v_pref.preference_axes->>'hierarchy_preference', '')::numeric;

  v_c_educ   := nullif(v_culture.culture_axes->>'education_support', '')::numeric;
  v_c_chal   := nullif(v_culture.culture_axes->>'challenge_openness', '')::numeric;
  v_c_brand  := nullif(v_culture.culture_axes->>'personal_brand_support', '')::numeric;
  v_c_collab := nullif(v_culture.culture_axes->>'team_collaboration', '')::numeric;
  v_c_auto   := nullif(v_culture.culture_axes->>'individual_autonomy', '')::numeric;
  v_c_flex   := nullif(v_culture.culture_axes->>'work_flexibility', '')::numeric;
  v_c_reldist:= nullif(v_culture.culture_axes->>'relationship_distance', '')::numeric;
  v_c_hier   := nullif(v_culture.culture_axes->>'hierarchy_flatness', '')::numeric;

  if v_s_educ is null or v_s_chal is null or v_s_brand is null or v_s_collab is null
     or v_s_auto is null or v_s_flex is null or v_s_reldist is null or v_s_hier is null
     or v_c_educ is null or v_c_chal is null or v_c_brand is null or v_c_collab is null
     or v_c_auto is null or v_c_flex is null or v_c_reldist is null or v_c_hier is null then
    return jsonb_build_object('available', false, 'reason', 'axes_incomplete');
  end if;

  v_m_educ   := 100 - abs(v_s_educ - v_c_educ);
  v_m_chal   := 100 - abs(v_s_chal - v_c_chal);
  v_m_brand  := 100 - abs(v_s_brand - v_c_brand);
  v_m_collab := 100 - abs(v_s_collab - v_c_collab);
  v_m_auto   := 100 - abs(v_s_auto - v_c_auto);
  v_m_flex   := 100 - abs(v_s_flex - v_c_flex);
  v_m_reldist:= 100 - abs(v_s_reldist - v_c_reldist);
  v_m_hier   := 100 - abs(v_s_hier - v_c_hier);

  v_overall := (v_m_educ + v_m_chal + v_m_brand + v_m_collab + v_m_auto + v_m_flex + v_m_reldist + v_m_hier) / 8;

  return jsonb_build_object(
    'available', true,
    'overall_score', round(v_overall),
    'axis_scores', jsonb_build_object(
      'education', round(v_m_educ), 'challenge', round(v_m_chal),
      'personal_brand', round(v_m_brand), 'collaboration', round(v_m_collab),
      'autonomy', round(v_m_auto), 'work_flexibility', round(v_m_flex),
      'relationship_distance', round(v_m_reldist), 'hierarchy', round(v_m_hier)
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_match_axes_by_store(p_stylist_user_id uuid, p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pref public.stylist_preference_profiles;
  v_culture public.salon_store_culture_profiles;
  v_s_educ numeric; v_s_chal numeric; v_s_brand numeric; v_s_collab numeric;
  v_s_auto numeric; v_s_flex numeric; v_s_reldist numeric; v_s_hier numeric;
  v_c_educ numeric; v_c_chal numeric; v_c_brand numeric; v_c_collab numeric;
  v_c_auto numeric; v_c_flex numeric; v_c_reldist numeric; v_c_hier numeric;
  v_m_educ numeric; v_m_chal numeric; v_m_brand numeric; v_m_collab numeric;
  v_m_auto numeric; v_m_flex numeric; v_m_reldist numeric; v_m_hier numeric;
  v_overall numeric;
begin
  select * into v_pref from public.stylist_preference_profiles where stylist_user_id = p_stylist_user_id;
  select * into v_culture from public.salon_store_culture_profiles where store_id = p_store_id;

  if v_pref.status is null or v_pref.status != 'completed' then
    return jsonb_build_object('available', false, 'reason', 'stylist_preference_incomplete');
  end if;
  if v_culture.status is null or v_culture.status != 'completed' then
    return jsonb_build_object('available', false, 'reason', 'salon_culture_incomplete');
  end if;

  v_s_educ   := nullif(v_pref.preference_axes->>'education_preference', '')::numeric;
  v_s_chal   := nullif(v_pref.preference_axes->>'challenge_preference', '')::numeric;
  v_s_brand  := nullif(v_pref.preference_axes->>'personal_brand_preference', '')::numeric;
  v_s_collab := nullif(v_pref.preference_axes->>'collaboration_preference', '')::numeric;
  v_s_auto   := nullif(v_pref.preference_axes->>'autonomy_preference', '')::numeric;
  v_s_flex   := nullif(v_pref.preference_axes->>'work_flexibility_preference', '')::numeric;
  v_s_reldist:= nullif(v_pref.preference_axes->>'relationship_distance_preference', '')::numeric;
  v_s_hier   := nullif(v_pref.preference_axes->>'hierarchy_preference', '')::numeric;

  v_c_educ   := nullif(v_culture.culture_axes->>'education_support', '')::numeric;
  v_c_chal   := nullif(v_culture.culture_axes->>'challenge_openness', '')::numeric;
  v_c_brand  := nullif(v_culture.culture_axes->>'personal_brand_support', '')::numeric;
  v_c_collab := nullif(v_culture.culture_axes->>'team_collaboration', '')::numeric;
  v_c_auto   := nullif(v_culture.culture_axes->>'individual_autonomy', '')::numeric;
  v_c_flex   := nullif(v_culture.culture_axes->>'work_flexibility', '')::numeric;
  v_c_reldist:= nullif(v_culture.culture_axes->>'relationship_distance', '')::numeric;
  v_c_hier   := nullif(v_culture.culture_axes->>'hierarchy_flatness', '')::numeric;

  if v_s_educ is null or v_s_chal is null or v_s_brand is null or v_s_collab is null
     or v_s_auto is null or v_s_flex is null or v_s_reldist is null or v_s_hier is null
     or v_c_educ is null or v_c_chal is null or v_c_brand is null or v_c_collab is null
     or v_c_auto is null or v_c_flex is null or v_c_reldist is null or v_c_hier is null then
    return jsonb_build_object('available', false, 'reason', 'axes_incomplete');
  end if;

  v_m_educ   := 100 - abs(v_s_educ - v_c_educ);
  v_m_chal   := 100 - abs(v_s_chal - v_c_chal);
  v_m_brand  := 100 - abs(v_s_brand - v_c_brand);
  v_m_collab := 100 - abs(v_s_collab - v_c_collab);
  v_m_auto   := 100 - abs(v_s_auto - v_c_auto);
  v_m_flex   := 100 - abs(v_s_flex - v_c_flex);
  v_m_reldist:= 100 - abs(v_s_reldist - v_c_reldist);
  v_m_hier   := 100 - abs(v_s_hier - v_c_hier);

  v_overall := (v_m_educ + v_m_chal + v_m_brand + v_m_collab + v_m_auto + v_m_flex + v_m_reldist + v_m_hier) / 8;

  return jsonb_build_object(
    'available', true,
    'overall_score', round(v_overall),
    'axis_scores', jsonb_build_object(
      'education', round(v_m_educ), 'challenge', round(v_m_chal),
      'personal_brand', round(v_m_brand), 'collaboration', round(v_m_collab),
      'autonomy', round(v_m_auto), 'work_flexibility', round(v_m_flex),
      'relationship_distance', round(v_m_reldist), 'hierarchy', round(v_m_hier)
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_stylist_salon_match(p_salon_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stylist_uid uuid := auth.uid();
begin
  if v_stylist_uid is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_roles where user_id = v_stylist_uid and role = 'stylist') then
    raise exception 'caller is not a stylist';
  end if;
  if not exists (select 1 from public.user_roles where user_id = p_salon_user_id and role = 'salon') then
    raise exception 'target is not a salon';
  end if;
  if not exists (select 1 from public.salon_profiles where user_id = p_salon_user_id and visibility = 'PUBLIC') then
    raise exception 'target salon is not public';
  end if;

  return public.calculate_match_axes(v_stylist_uid, p_salon_user_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_stylist_store_match(p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stylist_uid uuid := auth.uid();
begin
  if v_stylist_uid is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_roles where user_id = v_stylist_uid and role = 'stylist') then
    raise exception 'caller is not a stylist';
  end if;
  if not exists (select 1 from public.salon_store_profiles where store_id = p_store_id and visibility = 'PUBLIC') then
    raise exception 'target store is not public';
  end if;

  return public.calculate_match_axes_by_store(v_stylist_uid, p_store_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.decline_hiring_process(p_process_id uuid, p_public_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_p public.store_hiring_processes;
  v_note text := nullif(trim(coalesce(p_public_note, '')), '');
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_roles where user_id = v_uid and role = 'stylist') then
    raise exception 'caller is not a stylist';
  end if;
  if v_note is not null and char_length(v_note) > 1000 then
    raise exception 'note too long';
  end if;

  select * into v_p from public.store_hiring_processes
  where id = p_process_id and stylist_user_id = v_uid for update;
  if v_p.id is null then raise exception 'hiring process not found'; end if;
  if v_p.status in ('hired', 'declined', 'rejected') then
    raise exception 'hiring process is already closed';
  end if;

  update public.store_hiring_processes
  set status = 'declined', declined_by = 'stylist', closed_at = now(), updated_by_user_id = v_uid
  where id = v_p.id;

  insert into public.store_hiring_process_events (
    hiring_process_id, event_type, from_status, to_status, actor_user_id, actor_kind, public_note
  ) values (v_p.id, 'declined', v_p.status, 'declined', v_uid, 'stylist', v_note);

  return jsonb_build_object('id', v_p.id, 'status', 'declined');
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_stylist_evidence_document(p_document_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_path text;
begin
  delete from public.stylist_evidence_documents
  where id = p_document_id and stylist_user_id = v_uid
  returning storage_path into v_path;
  if v_path is null then raise exception 'document not found'; end if;
  update public.stylist_match_profiles
  set average_ticket = average_ticket
  where stylist_user_id = v_uid;
  return v_path;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_age_disclosure_requests()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_roles where user_id = v_uid and role = 'stylist') then raise exception 'caller is not a stylist'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'request_id', r.id, 'store_id', r.store_id, 'store_name', s.store_name, 'prefecture', s.prefecture, 'city', s.city,
      'status', r.status, 'requested_at', r.requested_at, 'decided_at', r.decided_at) order by r.requested_at desc)
    from public.age_disclosure_requests r join public.salon_stores s on s.id = r.store_id
    where r.stylist_user_id = v_uid), '[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_requested_role text := new.raw_user_meta_data->>'role';
  v_role public.user_role;
begin
  if v_requested_role in ('stylist', 'salon') then
    v_role := v_requested_role::public.user_role;
  else
    v_role := 'stylist';
  end if;

  insert into public.profiles (id, role)
  values (new.id, v_role);

  insert into public.user_settings (user_id)
  values (new.id);

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_scout_read(p_scout_id uuid)
 RETURNS scouts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row public.scouts;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;

  update public.scouts
  set read_status = 'read', read_at = coalesce(read_at, now())
  where id = p_scout_id and stylist_user_id = v_uid
  returning * into v_row;

  if v_row.id is null then raise exception 'scout not found'; end if;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_stylist_evidence_document(p_document_type text, p_storage_path text, p_original_file_name text)
 RETURNS stylist_evidence_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row public.stylist_evidence_documents;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_roles where user_id = v_uid and role = 'stylist') then
    raise exception 'caller is not a stylist';
  end if;
  if p_document_type not in ('pos_sales','payslip','performance_report','other') then
    raise exception 'invalid document type';
  end if;
  if p_storage_path !~ ('^' || v_uid::text || '/(pos_sales|payslip|performance_report|other)/[0-9a-f-]+\.(jpg|png|pdf)$') then
    raise exception 'invalid storage path';
  end if;
  if not exists (
    select 1 from storage.objects
    where bucket_id = 'stylist-evidence' and name = p_storage_path and owner = v_uid
  ) then raise exception 'evidence object not found'; end if;
  if (select count(*) from public.stylist_evidence_documents where stylist_user_id = v_uid) >= 5 then
    raise exception 'document limit reached';
  end if;
  if not exists (
    select 1 from public.stylist_match_profiles
    where stylist_user_id = v_uid and career_stage = 'results_stylist'
  ) then raise exception 'results profile required'; end if;

  insert into public.stylist_evidence_documents (
    stylist_user_id, document_type, storage_path, original_file_name
  ) values (
    v_uid, p_document_type, p_storage_path, left(trim(p_original_file_name), 180)
  ) returning * into v_row;

  update public.stylist_match_profiles
  set average_ticket = average_ticket
  where stylist_user_id = v_uid;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_age_disclosure_request(p_request_id uuid, p_approve boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid(); v_req public.age_disclosure_requests; v_want text; v_stylist_label text;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_approve is null then raise exception 'decision required'; end if;
  if not exists (select 1 from public.user_roles where user_id = v_uid and role = 'stylist') then raise exception 'caller is not a stylist'; end if;
  select * into v_req from public.age_disclosure_requests where id = p_request_id and stylist_user_id = v_uid for update;
  if not found then raise exception 'request not found'; end if;
  v_want := case when p_approve then 'approved' else 'declined' end;
  if v_req.status = 'pending' then
    update public.age_disclosure_requests set status = v_want, decided_at = now() where id = v_req.id returning * into v_req;
    if v_want = 'approved' and v_req.requested_by is not null then
      insert into public.notifications (user_id, type, title, message, related_entity_type, related_entity_id, link_path)
      values (v_req.requested_by, 'age_disclosure_approved', '実年齢の開示が承認されました',
              '依頼していた美容師が、実年齢の開示を承認しました。候補の画面で確認できます。',
              'age_disclosure_request', v_req.id, '/salon/stores/' || v_req.store_id::text || '/stylists')
      on conflict (user_id, type, related_entity_id) do nothing;
    end if;
  elsif v_req.status is distinct from v_want then
    raise exception 'age_disclosure_already_decided';
  end if;
  return jsonb_build_object('status', v_req.status);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_salary_offer(p_offer_id uuid, p_response text, p_reason text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS salary_offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row public.salary_offers;
  v_stylist_name text;
  v_notif_type text;
  v_title text;
  v_message text;
begin
  if p_response not in ('accepted','revision_requested','declined') then raise exception 'invalid response'; end if;
  if p_response='revision_requested' and (
    p_reason is null
    or p_reason not in ('workdays','guarantee_period','role','performance_basis','other')
  ) then
    raise exception 'reason required';
  end if;
  update public.salary_offers set status=p_response,
    response_reason=case when p_response='revision_requested' then p_reason end,
    response_note=case when p_response='revision_requested' then nullif(left(trim(coalesce(p_note,'')),500),'') end,
    responded_at=now()
  where id=p_offer_id and stylist_user_id=v_uid and status='pending'
  returning * into v_row;
  if v_row.id is null then raise exception 'offer not found'; end if;

  select public_name into v_stylist_name from public.stylist_profiles where user_id = v_uid;
  v_stylist_name := coalesce(v_stylist_name, '美容師') || 'さん';
  v_notif_type := case p_response
    when 'accepted' then 'salary_offer_accepted'
    when 'revision_requested' then 'salary_offer_revision_requested'
    else 'salary_offer_declined'
  end;
  v_title := case p_response
    when 'accepted' then v_stylist_name || 'が給与条件を承諾しました'
    when 'revision_requested' then v_stylist_name || 'から条件相談が届きました'
    else v_stylist_name || 'が給与条件を辞退しました'
  end;
  v_message := case p_response
    when 'accepted' then v_stylist_name || 'が提示した給与条件を承諾しました。'
    when 'revision_requested' then v_stylist_name || 'から条件について相談したいという連絡がありました。'
    else v_stylist_name || 'が今回の給与条件を辞退しました。'
  end;
  perform public.create_notification(v_row.salon_user_id, v_notif_type, v_title, v_message, 'salary_offer', v_row.id);

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_scout(p_scout_id uuid, p_response text, p_response_message text DEFAULT NULL::text)
 RETURNS scouts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_message text := nullif(trim(coalesce(p_response_message, '')), '');
  v_row public.scouts;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_response is null or p_response not in ('visit_requested','trial_requested','interested','question','considering','declined') then
    raise exception 'invalid response';
  end if;
  if p_response = 'question' and v_message is null then
    raise exception 'response message required';
  end if;
  if v_message is not null and char_length(v_message) > 1000 then
    raise exception 'response message too long';
  end if;

  update public.scouts
  set response_status = p_response,
      response_message = v_message,
      responded_at = now(),
      read_status = 'read',
      read_at = coalesce(read_at, now())
  where id = p_scout_id and stylist_user_id = v_uid and response_status = 'no_response'
  returning * into v_row;

  if v_row.id is null then raise exception 'scout not found or already responded'; end if;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_stylist_preference_profile(p_status stylist_preference_status, p_current_step integer, p_answers jsonb)
 RETURNS stylist_preference_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_axes jsonb;
  v_row public.stylist_preference_profiles;

  v_a1 numeric; v_a2 numeric; v_a3 numeric; v_a4 numeric;
  v_a5 numeric; v_a6 numeric; v_a7 numeric; v_a8 numeric;

  v_education numeric; v_challenge numeric; v_brand numeric; v_collab numeric;
  v_autonomy numeric; v_flexibility numeric; v_reldist numeric; v_hierarchy numeric;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  -- ★「1 auth user = 1 role」「user_rolesを正とする」という既存方針（0008
  -- user_roles_single_role.sql・lib/auth/user-roles.tsのhasCompletedRole()と
  -- 同じ判定基準）に合わせ、salon roleのユーザーがこのRPCを直接呼べない
  -- ようにする。stylist roleを持たない場合は例外にする（防御的処理。
  -- 通常はmiddleware/ページ側のrole guardで弾かれるが、RPCはSECURITY
  -- DEFINERであり、middlewareを経由しない直接呼び出しからも保護する）。
  if not exists (
    select 1 from public.user_roles where user_id = v_uid and role = 'stylist'
  ) then
    raise exception 'caller is not a stylist';
  end if;

  v_a1 := nullif((p_answers->>'q1_education_preference'), '')::numeric;
  v_a2 := nullif((p_answers->>'q2_challenge_preference'), '')::numeric;
  v_a3 := nullif((p_answers->>'q3_personal_brand_preference'), '')::numeric;
  v_a4 := nullif((p_answers->>'q4_collaboration_preference'), '')::numeric;
  v_a5 := nullif((p_answers->>'q5_autonomy_preference'), '')::numeric;
  v_a6 := nullif((p_answers->>'q6_work_flexibility_preference'), '')::numeric;
  v_a7 := nullif((p_answers->>'q7_relationship_distance_preference'), '')::numeric;
  v_a8 := nullif((p_answers->>'q8_hierarchy_preference'), '')::numeric;

  -- 1〜5の範囲外の値は不正な入力として扱い、未回答(null)にする（防御的処理）。
  if v_a1 is not null and (v_a1 < 1 or v_a1 > 5) then v_a1 := null; end if;
  if v_a2 is not null and (v_a2 < 1 or v_a2 > 5) then v_a2 := null; end if;
  if v_a3 is not null and (v_a3 < 1 or v_a3 > 5) then v_a3 := null; end if;
  if v_a4 is not null and (v_a4 < 1 or v_a4 > 5) then v_a4 := null; end if;
  if v_a5 is not null and (v_a5 < 1 or v_a5 > 5) then v_a5 := null; end if;
  if v_a6 is not null and (v_a6 < 1 or v_a6 > 5) then v_a6 := null; end if;
  if v_a7 is not null and (v_a7 < 1 or v_a7 > 5) then v_a7 := null; end if;
  if v_a8 is not null and (v_a8 < 1 or v_a8 > 5) then v_a8 := null; end if;

  -- 1→0, 2→25, 3→50, 4→75, 5→100
  v_education   := case when v_a1 is null then null else (v_a1 - 1) * 25 end;
  v_challenge   := case when v_a2 is null then null else (v_a2 - 1) * 25 end;
  v_brand       := case when v_a3 is null then null else (v_a3 - 1) * 25 end;
  v_collab      := case when v_a4 is null then null else (v_a4 - 1) * 25 end;
  v_autonomy    := case when v_a5 is null then null else (v_a5 - 1) * 25 end;
  v_flexibility := case when v_a6 is null then null else (v_a6 - 1) * 25 end;
  v_reldist     := case when v_a7 is null then null else (v_a7 - 1) * 25 end;
  v_hierarchy   := case when v_a8 is null then null else (v_a8 - 1) * 25 end;

  -- 未回答の軸はキー自体を含めない（jsonb_strip_nulls、salon_culture_profilesと同じ方針）。
  v_axes := jsonb_strip_nulls(jsonb_build_object(
    'education_preference', v_education,
    'challenge_preference', v_challenge,
    'personal_brand_preference', v_brand,
    'collaboration_preference', v_collab,
    'autonomy_preference', v_autonomy,
    'work_flexibility_preference', v_flexibility,
    'relationship_distance_preference', v_reldist,
    'hierarchy_preference', v_hierarchy
  ));

  insert into public.stylist_preference_profiles (
    stylist_user_id, status, current_step, answers, preference_axes
  ) values (
    v_uid, p_status, p_current_step, coalesce(p_answers, '{}'::jsonb), v_axes
  )
  on conflict (stylist_user_id) do update set
    status           = excluded.status,
    current_step     = excluded.current_step,
    answers          = excluded.answers,
    preference_axes  = excluded.preference_axes
  returning * into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_stylist_profile_v2(p_public_name text, p_full_name text, p_age_band age_band, p_gender gender_type, p_prefecture text, p_desired_work_location text, p_experience_years integer, p_current_position text, p_specialties text[], p_employment_type employment_type, p_job_change_intent job_change_intent, p_desired_salary_range salary_band, p_sns_links jsonb, p_bio text, p_visibility profile_visibility, p_scout_enabled boolean, p_avatar_path text, p_value_priorities text[], p_birth_date date, p_age_display_mode text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare
  v_profile public.profiles;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if p_birth_date is null then raise exception 'birth_date_required' using hint = '生年月日を登録してください'; end if;
  if p_age_display_mode is null or p_age_display_mode not in ('exact','decade') then
    raise exception 'age_display_mode_required' using hint = '年齢の表示方法を選択してください';
  end if;
  perform public.set_stylist_birth_date(p_birth_date);
  perform public.set_stylist_age_display_mode(p_age_display_mode);
  v_profile := public.save_stylist_profile(
    p_public_name, p_full_name, p_age_band, p_gender, p_prefecture, p_desired_work_location,
    p_experience_years, p_current_position, p_specialties, p_employment_type, p_job_change_intent,
    p_desired_salary_range, p_sns_links, p_bio, p_visibility, p_scout_enabled, p_avatar_path, p_value_priorities);
  return v_profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_stylist_profile_v4(p_public_name text, p_full_name text, p_age_band age_band, p_gender gender_type, p_prefecture text, p_desired_work_location text, p_experience_years integer, p_current_position text, p_specialties text[], p_employment_type employment_type, p_job_change_intent job_change_intent, p_desired_salary_range salary_band, p_sns_links jsonb, p_bio text, p_visibility profile_visibility, p_scout_enabled boolean, p_avatar_path text, p_value_priorities text[], p_birth_date date, p_age_display_mode text, p_career_phase text, p_graduation_ym date, p_blank_period_value integer, p_blank_period_unit text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Tokyo')::date;
  v_m0    date := date_trunc('month', v_today)::date;
  v_grad  date := case when p_graduation_ym is null then null else date_trunc('month', p_graduation_ym)::date end;
  v_max   integer;
  v_profile public.profiles;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  -- 立場と入力の検証（何かを保存する前）
  if p_career_phase is null or p_career_phase not in ('new_graduate','experienced','blank') then
    raise exception 'career_phase_required' using errcode = '23514', hint = '立場は「新卒」「現役の美容師」「ブランクあり」から選んでください';
  end if;
  if p_career_phase = 'new_graduate' then
    if p_blank_period_value is not null or p_blank_period_unit is not null then raise exception 'blank period must be empty for this phase'; end if;
    if v_grad is null then raise exception 'graduation month required'; end if;
    if extract(month from v_grad) not in (3, 10) then raise exception 'graduation_month_invalid' using errcode = '23514', hint = '卒業（予定）の月は3月か10月から選んでください'; end if;
    if v_grad < (v_m0 - interval '3 years') or v_grad > (v_m0 + interval '5 years') then raise exception 'graduation month out of range'; end if;
  elsif p_career_phase = 'experienced' then
    if v_grad is not null or p_blank_period_value is not null or p_blank_period_unit is not null then raise exception 'graduation and blank period must be empty for this phase'; end if;
  else
    if v_grad is not null then raise exception 'graduation must be empty for this phase'; end if;
    if (p_blank_period_value is null) <> (p_blank_period_unit is null) then raise exception 'blank period value and unit must be set together'; end if;
    if p_blank_period_value is not null then
      if p_blank_period_unit not in ('months','years') then raise exception 'invalid blank period unit'; end if;
      v_max := (case when p_blank_period_unit = 'months' then 720 else 60 end);
      if p_blank_period_value < 1 or p_blank_period_value > v_max then raise exception 'blank period out of range'; end if;
    end if;
  end if;

  v_profile := public.save_stylist_profile_v2(
    p_public_name, p_full_name, p_age_band, p_gender, p_prefecture, p_desired_work_location, p_experience_years, p_current_position,
    p_specialties, p_employment_type, p_job_change_intent, p_desired_salary_range, p_sns_links, p_bio, p_visibility, p_scout_enabled,
    p_avatar_path, p_value_priorities, p_birth_date, p_age_display_mode);

  -- 旧3項目（卒業の区分・就業開始・免許）は読まない・書かない（保存済みの値はそのまま残る）
  update public.stylist_profiles
     set career_phase = p_career_phase,
         graduation_ym = case when p_career_phase = 'new_graduate' then v_grad end,
         blank_period_value = case when p_career_phase = 'blank' then p_blank_period_value end,
         blank_period_unit = case when p_career_phase = 'blank' then p_blank_period_unit end
   where user_id = v_uid;
  if not found then raise exception 'stylist profile not found'; end if;
  return v_profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_favorite_salon(p_salon_user_id uuid, p_favorite boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stylist_uid uuid := auth.uid();
begin
  if v_stylist_uid is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1 from public.user_roles
    where user_id = v_stylist_uid and role = 'stylist'
  ) then
    raise exception 'caller is not a stylist';
  end if;

  if not exists (
    select 1
    from public.user_roles ur
    join public.salon_profiles sp on sp.user_id = ur.user_id
    where ur.user_id = p_salon_user_id
      and ur.role = 'salon'
      and sp.visibility = 'PUBLIC'
  ) then
    raise exception 'target salon is not public';
  end if;

  if p_favorite then
    insert into public.stylist_favorite_salons (stylist_user_id, salon_user_id)
    values (v_stylist_uid, p_salon_user_id)
    on conflict (stylist_user_id, salon_user_id) do nothing;
  else
    delete from public.stylist_favorite_salons
    where stylist_user_id = v_stylist_uid
      and salon_user_id = p_salon_user_id;
  end if;

  return p_favorite;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_store_interest_v2(p_store_id uuid, p_kind text, p_interested boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_roles where user_id = v_uid and role = 'stylist') then raise exception 'caller is not a stylist'; end if;
  if p_kind is null or p_kind not in ('visit', 'trial') then raise exception 'invalid interest kind'; end if;
  if p_interested is null then raise exception 'interested required'; end if;
  if p_interested then
    if not exists (select 1 from public.salon_store_profiles where store_id = p_store_id and visibility = 'PUBLIC') then raise exception 'target store is not public'; end if;
    if not exists (select 1 from public.stylist_salon_interests where stylist_user_id = v_uid and store_id = p_store_id and kind = p_kind) then
      perform public.assert_store_recruiting_allowed(p_store_id);
    end if;
    insert into public.stylist_salon_interests (stylist_user_id, store_id, kind) values (v_uid, p_store_id, p_kind)
      on conflict (stylist_user_id, store_id, kind) where store_id is not null do nothing returning id into v_id;
    -- 店舗の担当者への通知（と、そのメール送信待ち）は、トリガーが行う。
  else
    -- 種別と店舗で対象を特定して取り消す（もう一方の種別は残す）。取消は店舗の公開・停止状態にかかわらず可能。運営の受付・履歴は消えない（0087）。
    delete from public.stylist_salon_interests where stylist_user_id = v_uid and store_id = p_store_id and kind = p_kind returning id into v_id;
    if v_id is not null then
      perform public._cancel_interest_notifications(v_id, p_store_id, v_uid, p_kind);
    end if;
  end if;
  return p_interested;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_stylist_age_display_mode(p_mode text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_mode is null or p_mode not in ('exact','decade') then raise exception 'invalid age display mode'; end if;
  if exists (select 1 from public.user_roles where user_id = v_uid)
     and not exists (select 1 from public.user_roles where user_id = v_uid and role = 'stylist') then
    raise exception 'stylist role required';
  end if;
  insert into public.stylist_private (user_id, age_display_mode) values (v_uid, p_mode)
  on conflict (user_id) do update set age_display_mode = excluded.age_display_mode;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_stylist_birth_date(p_birth_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_age integer;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_birth_date is null then raise exception 'birth date required'; end if;
  if exists (select 1 from public.user_roles where user_id = v_uid)
     and not exists (select 1 from public.user_roles where user_id = v_uid and role = 'stylist') then
    raise exception 'stylist role required';
  end if;
  v_age := public.stylist_age_years(p_birth_date);
  if p_birth_date > (now() at time zone 'Asia/Tokyo')::date or v_age < 15 or v_age > 100 then
    raise exception 'invalid birth date';
  end if;
  insert into public.stylist_private (user_id, birth_date) values (v_uid, p_birth_date)
  on conflict (user_id) do update set birth_date = excluded.birth_date;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_stylist_value_priorities(p_value_priorities text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_allowed text[] := array[
    'work_life_balance','skill_growth','teamwork','independence','income_stability','customer_relationship',
    'education_support','brand_customer_base','work_flexibility','evaluation_fairness','location_convenience','culture_fit'];
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_value_priorities is null or array_ndims(p_value_priorities) is distinct from 1 or cardinality(p_value_priorities) <> 3 then
    raise exception 'invalid_value_priorities: exactly 3 items required' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(p_value_priorities) c where c is null) then
    raise exception 'invalid_value_priorities: null item' using errcode = '22023';
  end if;
  if (select count(distinct c) from unnest(p_value_priorities) c) <> 3 then
    raise exception 'invalid_value_priorities: duplicate items' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(p_value_priorities) c where c <> all (v_allowed)) then
    raise exception 'invalid_value_priorities: item not allowed' using errcode = '22023';
  end if;
  -- この1列だけを、本人の行にだけ書く。他の列は SET に含めない。
  update public.stylist_profiles set value_priorities = p_value_priorities where user_id = v_uid;
  if not found then
    raise exception 'profile_not_found' using errcode = 'P0002';
  end if;
end;
$function$
